    "question_id": "gold-ths-coronaire",
    "sous_question": "Chez la femme ménopausée sans maladie coronaire connue, un traitement hormonal associant œstrogène et progestatif réduit-il le risque de maladie coronaire ?",
    "espece_cible": "human_in_vivo",
    "population": "femmes ménopausées sans maladie coronaire connue, suivies aux États-Unis",
    "intervention": "œstrogène associé à un progestatif par voie orale, contre absence de traitement hormonal ou placebo",
    "mesurande": {
      "nom": "maladie coronaire (infarctus non fatal ou décès coronarien)",
      "unite": "risque relatif"
    },
    "exclusions": [],
    "requetes_initiales": {
      "pubmed": [
        "estrogen progestin coronary heart disease postmenopausal"
      ],
      "arxiv": []
    }
  },
  "citation_verbatim": "We observed a marked decrease in the risk of major coronary heart disease among women who took estrogen with progestin (multivariate adjusted relative risk, 0.39; 95 percent confidence interval, 0.19 to 0.78)",
  "source_id": "pmid:8672166",
  "drapeaux": {
    "is_future_or_protocol": false,
